import torch, triton, triton.language as tl

x = torch.rand(16, 64, 256, 256, device='cuda')
N = 64*256*256; rows = 16
w = torch.rand(N, device='cuda'); b = torch.rand(N, device='cuda')
out = torch.empty_like(x)
acc = torch.zeros(2, rows, device='cuda')
TOT = x.numel()

def hot(fn, n=50):
    for _ in range(3): fn()
    torch.cuda.synchronize()
    s=torch.cuda.Event(enable_timing=True); e=torch.cuda.Event(enable_timing=True)
    s.record()
    for _ in range(n): fn()
    e.record(); torch.cuda.synchronize()
    return s.elapsed_time(e)/n

@triton.jit
def _apply3(x_ptr, w_ptr, b_ptr, s_ptr, q_ptr, o_ptr, N, eps, BLOCK: tl.constexpr, NLOOP: tl.constexpr,
            XEV: tl.constexpr, OEV: tl.constexpr):
    pid = tl.program_id(0); row = tl.program_id(1)
    s = tl.load(s_ptr + row); q = tl.load(q_ptr + row)
    mean = s/N; var = q/N - mean*mean
    rstd = 1.0/tl.sqrt(var+eps)
    for i in tl.static_range(NLOOP):
        offs = (pid*NLOOP+i)*BLOCK + tl.arange(0, BLOCK)
        mask = offs < N
        base = row*N+offs
        xv = tl.load(x_ptr+base, mask=mask, other=0., eviction_policy=XEV)
        wv = tl.load(w_ptr+offs, mask=mask, other=0.)
        bv = tl.load(b_ptr+offs, mask=mask, other=0.)
        tl.store(o_ptr+base, (xv-mean)*rstd*wv+bv, mask=mask, eviction_policy=OEV)

@triton.jit
def _copy3(x_ptr, o_ptr, TOT, BLOCK: tl.constexpr, NLOOP: tl.constexpr, XEV: tl.constexpr, OEV: tl.constexpr):
    pid = tl.program_id(0)
    for i in tl.static_range(NLOOP):
        offs = (pid*NLOOP+i)*BLOCK + tl.arange(0, BLOCK)
        mask = offs < TOT
        v = tl.load(x_ptr+offs, mask=mask, other=0., eviction_policy=XEV)
        tl.store(o_ptr+offs, v, mask=mask, eviction_policy=OEV)

@triton.jit
def _stats3(x_ptr, s_ptr, q_ptr, N, BLOCK: tl.constexpr, NLOOP: tl.constexpr, XEV: tl.constexpr):
    pid = tl.program_id(0); row = tl.program_id(1)
    sacc = tl.zeros([BLOCK], dtype=tl.float32)
    qacc = tl.zeros([BLOCK], dtype=tl.float32)
    for i in tl.static_range(NLOOP):
        offs = (pid*NLOOP+i)*BLOCK + tl.arange(0, BLOCK)
        mask = offs < N
        v = tl.load(x_ptr+row*N+offs, mask=mask, other=0., eviction_policy=XEV)
        sacc += v
        qacc += v*v
    tl.atomic_add(s_ptr+row, tl.sum(sacc, axis=0))
    tl.atomic_add(q_ptr+row, tl.sum(qacc, axis=0))

print('--- copy3 sweep ---')
for B,W,L in [(2048,4,4),(2048,4,8),(2048,4,16),(4096,8,4),(4096,8,8),(1024,4,8),(1024,4,16),(8192,16,4)]:
    try:
        t = hot(lambda: _copy3[(triton.cdiv(TOT,B*L),)](x, out, TOT, BLOCK=B, NLOOP=L, XEV='evict_first', OEV='evict_first', num_warps=W))
        print(f'copy3 B={B} W={W} L={L}: {t:.4f} ({536.9/t:.0f} GB/s eff)')
    except Exception as ex:
        print(f'copy3 B={B} W={W} L={L}: FAIL {type(ex).__name__}')

print('--- apply3 sweep ---')
for B,W,L in [(1024,4,8),(1024,4,16),(1024,4,32),(2048,4,8),(2048,4,16),(2048,4,32),(2048,8,8),(2048,8,16),(4096,8,8),(4096,8,16),(4096,16,8)]:
    try:
        t = hot(lambda: _apply3[(triton.cdiv(N,B*L), rows)](x, w, b, acc[0], acc[1], out, N, 1e-5, BLOCK=B, NLOOP=L, XEV='evict_first', OEV='evict_first', num_warps=W))
        print(f'apply3 B={B} W={W} L={L}: {t:.4f}')
    except Exception as ex:
        print(f'apply3 B={B} W={W} L={L}: FAIL {type(ex).__name__}')

print('--- apply3 ev combos best cfg ---')
for xe,oe in [('',''),('evict_first',''),('','evict_first'),('evict_first','evict_first')]:
    t = hot(lambda: _apply3[(triton.cdiv(N,2048*8), rows)](x, w, b, acc[0], acc[1], out, N, 1e-5, BLOCK=2048, NLOOP=8, XEV=xe, OEV=oe, num_warps=4))
    print(f'apply3 B=2048 W=4 L=8 xev={xe!r} oev={oe!r}: {t:.4f}')

print('--- stats3 sweep ---')
for B,W,L in [(1024,4,8),(2048,4,4),(2048,4,8),(2048,4,16),(4096,8,4),(4096,8,8),(8192,16,4)]:
    try:
        t = hot(lambda: _stats3[(triton.cdiv(N,B*L), rows)](x, acc[0], acc[1], N, BLOCK=B, NLOOP=L, XEV='evict_first', num_warps=W))
        print(f'stats3 B={B} W={W} L={L}: {t:.4f}')
    except Exception as ex:
        print(f'stats3 B={B} W={W} L={L}: FAIL {type(ex).__name__}')
